.tm-field-row { display: flex; align-items: center; gap: 8px; }
.tm-options-area { }
.tm-option-header { margin: 6px 0 4px; }
.tm-option-row { display: flex; align-items: center; gap: 6px; margin-bottom: 4px; }
.tm-option-row .tm-input { flex: 1; }
.tm-form-footer { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; padding-top: 12px; border-top: 1px solid var(--border); }
.tm-form-empty { display: flex; flex-direction: column; align-items: center; justify-content: center; height: 100%; min-height: 200px; color: var(--text-dim); font-size: 13px; gap: 8px; }
.tm-form-empty-icon { font-size: 40px; }

