.djs-minimap { background: var(--surface) !important; border: 1px solid var(--border) !important; border-radius: 4px !important; box-shadow: 0 4px 20px rgba(0,0,0,.5) !important; }
.djs-minimap .minimap-toggle-parent button { background: var(--surface2) !important; color: var(--text) !important; border-color: var(--border) !important; }
