  border-bottom: 1px solid var(--border);\n  display: flex;\n  align-items: center;\n  padding: 0 10px;\n  gap: 4px;\n  flex-shrink: 0;\n  user-select: none;\n  -webkit-app-region: no-drag;\n}\n\n.tb-group { display: flex; align-items: center; gap: 2px; }\n\n.tb-sep {\n  width: 1px; height: 22px;\n  background: var(--border);\n  margin: 0 4px;\n}\n\n.tb-spacer { flex: 1; }\n\n.tb-btn {\n  display: inline-flex; align-items: center; gap: 5px;\n  padding: 4px 9px;\n  background: transparent;\n  border: 1px solid transparent;\n  border-radius: 4px;\n  color: var(--text);\n  font-size: 12px;\n  cursor: pointer;\n  white-space: nowrap;\n  transition: background .1s, border-color .1s;\n  line-height: 1;\n}\n.tb-btn svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; flex-shrink: 0; }\n.tb-btn:hover  { background: var(--surface2); border-color: var(--border); }\n.tb-btn:active { background: #1e3a6a; border-color: var(--accent); color: #fff; }\n.tb-btn:disabled { opacity: .4; cursor: not-allowed; }\n.tb-btn-icon { padding: 4px 8px; }\n.tb-btn.active { background: var(--surface2); border-color: var(--accent); color: #7eb8ff; }\n\n.tb-btn-validate { color: #81c784; }\n.tb-btn-validate:hover  { background: #1e3a1e; }\n.tb-btn-validate.active { background: #1e3a1e; border-color: #4caf50; }\n\n.tb-btn-xml { color: #ce9178; }\n.tb-btn-xml:hover  { background: #2a1e14; }\n.tb-btn-xml.active { background: #2a1e14; border-color: #ce9178; }\n\n.tb-btn-minimap  { color: var(--info);   }\n.tb-btn-minimap:hover  { background: #1a2b3d; }\n\n.tb-btn-templates { color: var(--purple); }\n.tb-btn-templates:hover { background: #2a1a4a; }\n\n.tb-btn-deploy { color: #7eb8ff; }\n.tb-btn-deploy:hover { background: #1a2a4a; }\n\n.file-label {\n  font-size: 11px;\n  color: var(--text-dim);\n  padding: 2px 8px;\n  background: var(--surface2);\n  border: 1px solid var(--border);\n  border-radius: 3px;\n  max-width: 340px;